// 整数同士の割り算は 0 方向へ切り捨て。数値を変えてみよう
int a = -7;
int b = 2;
System.out.println(a + " / " + b + " = " + (a / b));
System.out.println(a + " % " + b + " = " + (a % b));
System.out.println("floorDiv = " + Math.floorDiv(a, b));
System.out.println("floorMod = " + Math.floorMod(a, b));

// どちらかを double にすると小数まで計算される
System.out.println(a / 2.0);

// double のゼロ除算は例外にならない
System.out.println(10.0 / 0);
System.out.println(0.0 / 0);

// ↓ 行頭の // を外すと int のゼロ除算で ArithmeticException が出る
// System.out.println(10 / 0);

// 後置 i++ は「増やす前」の値、前置 ++i は「増やした後」の値
int i = 5;
int x = i++;
System.out.println("x = " + x + ", i = " + i);
int y = ++i;
System.out.println("y = " + y + ", i = " + i);

// i = i++ の罠。j の初期値を変えて試してみよう
int j = 10;
j = j++;
System.out.println("j = " + j);

// 複合代入には暗黙のキャストが入る(127 を 100 などに変えてみよう)
byte bt = 127;
bt += 1;
System.out.println("bt = " + bt);

// 文字列連結は左から順に評価される
System.out.println("1" + 2 + 3);
System.out.println(1 + 2 + "3");
System.out.println("合計: " + 1 + 2);
System.out.println("合計: " + (1 + 2));

// 短絡評価: count を 0 以外にすると右側の割り算も実行される
int count = 0;
int total = 100;
System.out.println(count != 0 && total / count > 10);
// && を & に変えると? (count が 0 のままだと例外になる)

// 三項演算子: score を変えてみよう
int score = 72;
String result = score >= 60 ? "合格" : "不合格";
System.out.println(score + "点 → " + result);

// 文字列の比較は equals
String s1 = "hello";
String s2 = new String("hello");
System.out.println("== : " + (s1 == s2));
System.out.println("equals : " + s1.equals(s2));

// 割り勘と BMI を Math クラスで計算してみる。数値を変えてみよう
int bill = 10000;
int people = 3;
System.out.println("1人あたり: " + (bill / people) + "円, 端数: " + (bill % people) + "円");

double heightCm = 170;
double weightKg = 65;
double heightM = heightCm / 100;
double bmi = weightKg / (heightM * heightM);
System.out.println("BMI(そのまま): " + bmi);
System.out.println("BMI(小数第1位): " + Math.round(bmi * 10) / 10.0);
// ↑ 10.0 を 10 にすると? 整数除算になって小数が消える

System.out.println(Math.pow(2, 10));   // double で返る
System.out.println(Math.max(3, 7) + ", " + Math.min(3, 7) + ", " + Math.abs(-5));
System.out.println(Math.round(2.5) + ", " + Math.round(-2.5));  // -2.5 は -2 になる

